import torch.nn as nn
import torch.nn.functional as F

# Set float32 matmul precision for better performance on AMD
torch.set_float32_matmul_precision('high')


class ModelNew(nn.Module):
    """
    Optimized implementation using PyTorch's scaled_dot_product_attention with torch.compile.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Compile the forward method for better performance
        self.forward = torch.compile(self.forward, mode="default")

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return F.scaled_dot_product_attention(Q, K, V)
"}

